def make(n):
    # Produce: ( ( ( python_version == '3.8' ) ) ... )
    inner = "python_version == '3.8'"
    for _ in range(n):
        inner = f'({inner})'
    return [[inner]]

def make(n):
    inner = "python_version > '3.0'"
    for i in range(1, n+1):
        inner = f"(python_version > '3.{i}' and {inner})"
    return [[inner]]
